from openai import AzureOpenAI
import os


def get_azure_openai_client(config):
    return AzureOpenAI(
        azure_endpoint=config.get("AZURE_OPENAI_ENDPOINT") or os.getenv("AZURE_OPENAI_ENDPOINT"),
        api_key=config.get("AZURE_OPENAI_API_KEY") or os.getenv("AZURE_OPENAI_API_KEY"),
        api_version=config.get("AZURE_OPENAI_API_VERSION", "2024-02-01"),
    )

from dataclasses import dataclass
from typing import Dict, Any, Optional


@dataclass
class PlatformModelPayload:
    text: str


@dataclass
class PlatformModelOutput:
    text: str
    metadata: Optional[Dict[str, Any]] = None

from model_client import get_azure_openai_client
from model_models import PlatformModelPayload
import os


def stream_platform_generation(payload: PlatformModelPayload, config: dict = None):
    config = config or {}
    client = get_azure_openai_client(config)
    deployment_id = config.get("AZURE_OPENAI_DEPLOYMENT_ID") or os.getenv("AZURE_OPENAI_DEPLOYMENT_ID")

    if not deployment_id:
        raise ValueError("Azure OpenAI deployment ID not found in config or environment variables.")

    stream = client.chat.completions.create(
        model=deployment_id,
        messages=[{"role": "user", "content": payload.text}],
        stream=True,
    )
    for chunk in stream:
        if chunk.choices and chunk.choices[0].delta.content is not None:
            yield {"text": chunk.choices[0].delta.content}

from azure.core.credentials import AzureKeyCredential
from azure.ai.contentsafety import ContentSafetyClient
from azure.ai.contentsafety.models import AnalyzeTextOptions, TextCategory
import os


def check_platform_output_safety(text: str, config: dict = None) -> dict:
    config = config or {}
    endpoint = config.get("AZURE_CONTENT_SAFETY_ENDPOINT") or os.getenv("AZURE_CONTENT_SAFETY_ENDPOINT")
    key = config.get("AZURE_CONTENT_SAFETY_KEY") or os.getenv("AZURE_CONTENT_SAFETY_KEY")

    if not endpoint or not key:
        raise ValueError("Azure Content Safety endpoint and key not found in config or environment variables.")

    client = ContentSafetyClient(endpoint, AzureKeyCredential(key))

    request = AnalyzeTextOptions(text=text)

    try:
        response = client.analyze_text(request)
        # Process the response to determine if it's safe
        # This is a simplified example, real world would involve checking each category and its severity
        is_safe = True
        safety_results = {}
        if response.categories_analysis:
            for category_analysis in response.categories_analysis:
                safety_results[category_analysis.category.value] = {
                    "severity": category_analysis.severity,
                    "is_unsafe": category_analysis.severity > 0
                }
                if category_analysis.severity > 0:
                    is_safe = False

        return {"is_safe": is_safe, "analysis_results": safety_results}

    except Exception as e:
        return {"error": str(e), "is_safe": False}

import requests
import uuid
import os

def translate_platform_output(text: str, target_language: str, config: dict = None) -> dict:
    config = config or {}
    key = config.get("AZURE_TRANSLATOR_TEXT_KEY") or os.getenv("AZURE_TRANSLATOR_TEXT_KEY")
    endpoint = config.get("AZURE_TRANSLATOR_TEXT_ENDPOINT") or os.getenv("AZURE_TRANSLATOR_TEXT_ENDPOINT")
    location = config.get("AZURE_TRANSLATOR_TEXT_LOCATION") or os.getenv("AZURE_TRANSLATOR_TEXT_LOCATION")

    if not key or not endpoint or not location:
        raise ValueError("Azure Translator Text API key, endpoint, and location not found in config or environment variables.")

    path = '/translate'
    constructed_url = endpoint + path

    headers = {
        'Ocp-Apim-Subscription-Key': key,
        'Ocp-Apim-Subscription-Region': location,
        'Content-type': 'application/json',
        'X-ClientTraceId': str(uuid.uuid4())
    }

    params = {
        'api-version': '3.0',
        'to': target_language
    }

    body = [{'text': text}]

    try:
        request = requests.post(constructed_url, params=params, headers=headers, json=body)
        response = request.json()

        if request.status_code == 200 and response and len(response) > 0 and 'translations' in response[0] and len(response[0]['translations']) > 0:
            translated_text = response[0]['translations'][0]['text']
            return {"translated_text": translated_text}
        else:
            return {"error": "Translation failed or returned empty response.", "response": response}

    except Exception as e:
        return {"error": str(e)}

from openai import AzureOpenAI
import os


def embed_platform_output(text: str, config: dict = None) -> dict:
    config = config or {}
    client = AzureOpenAI(
        azure_endpoint=config.get("AZURE_OPENAI_ENDPOINT") or os.getenv("AZURE_OPENAI_ENDPOINT"),
        api_key=config.get("AZURE_OPENAI_API_KEY") or os.getenv("AZURE_OPENAI_API_KEY"),
        api_version=config.get("AZURE_OPENAI_API_VERSION", "2024-02-01"), # Embedding API versions can be different
    )

    # The embedding model deployment ID should be different from the chat model deployment ID
    embedding_deployment_id = config.get("AZURE_OPENAI_EMBEDDING_DEPLOYMENT_ID") or os.getenv("AZURE_OPENAI_EMBEDDING_DEPLOYMENT_ID")

    if not embedding_deployment_id:
        raise ValueError("Azure OpenAI Embedding deployment ID not found in config or environment variables.")

    try:
        response = client.embeddings.create(input=text, model=embedding_deployment_id)
        if response.data and len(response.data) > 0:
            embedding = response.data[0].embedding
            return {"embedding": embedding, "usage": response.usage.model_dump() if response.usage else None}
        else:
            return {"error": "Failed to generate embedding or empty response."}

    except Exception as e:
        return {"error": str(e)}

import azure.cognitiveservices.speech as speechsdk
import os


def generate_platform_brief_audio(text: str, config: dict = None, output_file: str = "output.wav") -> dict:
    config = config or {}
    speech_key = config.get("AZURE_SPEECH_KEY") or os.getenv("AZURE_SPEECH_KEY")
    service_region = config.get("AZURE_SPEECH_REGION") or os.getenv("AZURE_SPEECH_REGION")

    if not speech_key or not service_region:
        raise ValueError("Azure Speech Service key and region not found in config or environment variables.")

    # Configure the speech synthesis
    speech_config = speechsdk.SpeechConfig(subscription=speech_key, region=service_region)

    # You can specify a voice, e.g., "en-US-AvaMultilingualNeural"
    # A list of supported voices can be found here: 
    # https://learn.microsoft.com/en-us/azure/ai-services/speech-service/language-support?tabs=text-to-speech#standard-voices
    speech_config.speech_synthesis_voice_name = config.get("AZURE_SPEECH_VOICE_NAME", "en-US-JennyNeural")

    # Use the default speaker as audio output. This will play the audio.
    # To save to a file, use AudioOutputConfig.from_wav_file(output_file)
    audio_config = speechsdk.AudioOutputConfig(filename=output_file)

    speech_synthesizer = speechsdk.SpeechSynthesizer(speech_config=speech_config, audio_config=audio_config)

    try:
        result = speech_synthesizer.speak_text_async(text).get()

        if result.reason == speechsdk.ResultReason.SynthesizingAudioCompleted:
            return {"status": "success", "audio_file": output_file, "message": "Speech synthesis completed."}
        elif result.reason == speechsdk.ResultReason.Canceled:
            cancellation_details = result.cancellation_details
            return {"status": "cancelled", "error": cancellation_details.error_details, "reason": cancellation_details.reason}
    except Exception as e:
        return {"status": "error", "error": str(e)}

    return {"status": "error", "message": "An unknown error occurred during speech synthesis."}
